package com.afterglow.player;

import android.app.AlertDialog;
import android.graphics.*;
import android.graphics.drawable.GradientDrawable;
import android.view.*;
import android.widget.*;
import java.io.File;
import java.util.*;

/** A compact queue sheet. Preview order is local until the finger is released. */
final class QueueSheet extends LinearLayout {
 final MainActivity a; final ScrollView scroll; final LinearLayout rows; final LinearLayout nowContainer; Track shownTrack; Button nowPlay;
 final ArrayList<Track> order=new ArrayList<>(); final Map<Track,View> cards=new IdentityHashMap<>();
 View lifted;Track dragged;float fingerY,grabOffset; boolean active;
 final Runnable edgeScroll=new Runnable(){public void run(){if(!active)return;int[] xy=new int[2];scroll.getLocationOnScreen(xy);float y=fingerY-xy[1];int delta=y<a.dp(56)?-a.dp(8):y>scroll.getHeight()-a.dp(56)?a.dp(8):0;if(delta!=0){scroll.scrollBy(0,delta);positionDrag();}postDelayed(this,16);}};
 QueueSheet(MainActivity activity){super(activity);a=activity;setOrientation(VERTICAL);setPadding(a.dp(20),a.dp(12),a.dp(20),a.dp(16));GradientDrawable bg=a.shape(0xff202020,24);setBackground(bg);
  View grip=new View(a);grip.setBackground(a.shape(0xff666666,4));LayoutParams gp=new LayoutParams(a.dp(36),a.dp(4));gp.gravity=Gravity.CENTER_HORIZONTAL;gp.bottomMargin=a.dp(12);addView(grip,gp);
  LinearLayout heading=a.row();TextView title=a.text("Queue",26,Color.WHITE);title.setTypeface(null,Typeface.BOLD);heading.addView(title,new LayoutParams(0,a.dp(48),1));Button close=a.button("×",()->{if(a.queueDialog!=null)a.queueDialog.dismiss();});close.setContentDescription("Close queue");close.setBackgroundColor(Color.TRANSPARENT);heading.addView(close,new LayoutParams(a.dp(48),a.dp(48)));addView(heading);LinearLayout queueActions=a.row();Button shuffle=a.button("Shuffle queue",()->{a.service.shuffleUpcoming();refresh();});a.addSpacedControl(queueActions,shuffle);Button clear=a.button("Clear queue",()->{cancelDrag();a.service.clearUpcoming();refresh();a.toast("Queue cleared");});a.addSpacedControl(queueActions,clear);addView(queueActions);
  addView(a.text("Now playing",12,0xffaaaaaa));nowContainer=a.column();addView(nowContainer);
  addView(a.text("Up next · drag the handle to reorder",12,0xffaaaaaa));scroll=new ScrollView(a);scroll.setFillViewport(false);rows=a.column();rows.setClipChildren(false);scroll.addView(rows);addView(scroll,new LayoutParams(-1,0,1));refresh();
 }
 LinearLayout trackRow(Track track,boolean current){LinearLayout card=a.row();card.setPadding(0,a.dp(8),0,a.dp(8));card.setMinimumHeight(a.dp(76));FrameLayout art=new FrameLayout(a);TextView note=a.text("♫",23,0xffaaaaaa);note.setGravity(Gravity.CENTER);note.setBackground(a.shape(0xff343434,5));art.addView(note,new FrameLayout.LayoutParams(-1,-1));ImageView image=new ImageView(a);image.setScaleType(ImageView.ScaleType.CENTER_CROP);art.addView(image,new FrameLayout.LayoutParams(-1,-1));LayoutParams artParams=new LayoutParams(a.dp(52),a.dp(52));artParams.rightMargin=a.dp(12);card.addView(art,artParams);
  a.executor.execute(()->{Bitmap bitmap=null;try{File cached=new File(a.getCacheDir(),"art-"+track.uri+".jpg");BitmapFactory.Options opts=new BitmapFactory.Options();opts.inSampleSize=4;if(cached.isFile())bitmap=BitmapFactory.decodeFile(cached.getPath(),opts);else if("local".equals(track.kind)&&!"demo".equals(track.uri)){android.media.MediaMetadataRetriever retriever=new android.media.MediaMetadataRetriever();try{retriever.setDataSource(a,android.net.Uri.parse(track.uri));byte[] data=retriever.getEmbeddedPicture();if(data!=null)bitmap=BitmapFactory.decodeByteArray(data,0,data.length,opts);}finally{retriever.release();}}}catch(Exception ignored){}final Bitmap result=bitmap;image.post(()->{if(result!=null)image.setImageBitmap(result);});});
  LinearLayout labels=a.column();TextView title=a.text(track.title,16,current?a.accent:Color.WHITE);title.setSingleLine();title.setEllipsize(android.text.TextUtils.TruncateAt.END);title.setPadding(0,0,0,a.dp(4));labels.addView(title);TextView artist=a.text(track.artist,13,0xffaaaaaa);artist.setSingleLine();artist.setEllipsize(android.text.TextUtils.TruncateAt.END);artist.setPadding(0,0,0,0);labels.addView(artist);card.addView(labels,new LayoutParams(0,-2,1));return card;
 }
 void refresh(){if(active)return;if(shownTrack!=a.service.current()){shownTrack=a.service.current();nowContainer.removeAllViews();LinearLayout now=trackRow(shownTrack,true);nowPlay=a.button("▶",()->{a.service.toggle();refresh();});nowPlay.setContentDescription("Play or pause");now.addView(nowPlay,new LayoutParams(a.dp(48),a.dp(48)));nowContainer.addView(now);}nowPlay.setText(a.service.playing()?"Ⅱ":"▶");order.clear();order.addAll(a.service.upcoming);cards.clear();rows.removeAllViews();if(order.isEmpty()){rows.addView(a.text("Your queue is empty. Add songs from your library.",14,0xffaaaaaa));return;}for(Track track:order){LinearLayout card=trackRow(track,false);View handle=new View(a){final Paint paint=new Paint(3);protected void onDraw(Canvas c){paint.setColor(0xffaaaaaa);paint.setStrokeWidth(a.dp(2));for(int i=-1;i<=1;i++)c.drawLine(getWidth()/2f-a.dp(8),getHeight()/2f+i*a.dp(5),getWidth()/2f+a.dp(8),getHeight()/2f+i*a.dp(5),paint);}};handle.setContentDescription("Drag to reorder "+track.title);handle.setFocusable(true);handle.setOnClickListener(v->choosePosition(track));handle.setOnTouchListener((v,event)->touch(card,track,event));card.addView(handle,new LayoutParams(a.dp(48),a.dp(56)));card.setOnLongClickListener(v->{new AlertDialog.Builder(a).setTitle(track.title).setItems(new String[]{"Remove from queue"},(d,n)->{a.service.dequeue(track);refresh();}).show();return true;});rows.addView(card,new LayoutParams(-1,a.dp(76)));cards.put(track,card);}}
 void choosePosition(Track track){String[] choices=new String[order.size()];for(int i=0;i<choices.length;i++)choices[i]="Move to position "+(i+1);new AlertDialog.Builder(a).setTitle("Reorder "+track.title).setItems(choices,(d,n)->{a.service.moveTrack(track,n);refresh();}).show();}
 boolean touch(View card,Track track,MotionEvent event){switch(event.getActionMasked()){case MotionEvent.ACTION_DOWN:active=true;a.draggingQueue=true;lifted=card;dragged=track;fingerY=event.getRawY();int[] xy=new int[2];card.getLocationOnScreen(xy);grabOffset=fingerY-xy[1];card.animate().cancel();card.setElevation(a.dp(12));card.setBackground(a.shape(0xff383838,8));card.performHapticFeedback(HapticFeedbackConstants.LONG_PRESS);scroll.requestDisallowInterceptTouchEvent(true);post(edgeScroll);return true;case MotionEvent.ACTION_MOVE:fingerY=event.getRawY();positionDrag();return true;case MotionEvent.ACTION_UP:finishDrag(true);return true;case MotionEvent.ACTION_CANCEL:finishDrag(false);return true;default:return true;}}
 void positionDrag(){if(!active||lifted==null)return;int[] xy=new int[2];rows.getLocationOnScreen(xy);float top=fingerY-xy[1]-grabOffset;int from=order.indexOf(dragged),to=Math.max(0,Math.min(order.size()-1,(int)((top+lifted.getHeight()/2f)/a.dp(76))));if(from!=to){order.remove(from);order.add(to,dragged);for(int i=0;i<order.size();i++){View card=cards.get(order.get(i));if(card!=lifted){float target=i*a.dp(76)-card.getTop();card.animate().translationY(target).setDuration(140).start();}}}lifted.setTranslationY(top-lifted.getTop());}
 void finishDrag(boolean commit){if(!active)return;removeCallbacks(edgeScroll);if(commit&&a.service.upcoming.contains(dragged))a.service.moveTrack(dragged,order.indexOf(dragged));active=false;a.draggingQueue=false;scroll.requestDisallowInterceptTouchEvent(false);if(lifted!=null){lifted.setElevation(0);lifted=null;}refresh();}
 void cancelDrag(){finishDrag(false);removeCallbacks(edgeScroll);}
 protected void onDetachedFromWindow(){removeCallbacks(edgeScroll);active=false;a.draggingQueue=false;super.onDetachedFromWindow();}
}
